//! A typed session over a generated chart: start it, send typed events, ask which states are
//! active.

use std::fmt;
use std::sync::Arc;

use vertep_core::compile::{CompiledChart, StateIdx};
use vertep_core::datamodel::{Environment, Event, SessionInfo};
use vertep_core::ir::{Chart, StateKind};
use vertep_core::session::{
    self, Effect, Input, Outcome, Session, StartError, StartInput, StepError,
};

use crate::datamodel::{Context, RustDatamodel};
use crate::emit::ChartEvent;
use crate::registry::{Registry, RegistryError};

/// A chart's typed state enum, generated by the macros: one variant per state, mirroring the
/// state hierarchy through [`StateEnum::parent`] and [`StateEnum::children`].
pub trait StateEnum: Copy + Eq + fmt::Debug + 'static {
    /// Every state in document order.
    const ALL: &'static [Self];

    /// The position of this state in [`StateEnum::ALL`].
    fn index(self) -> usize;

    /// The state identifier.
    fn id(self) -> &'static str;

    /// The kind of state.
    fn kind(self) -> StateKind;

    /// The parent state, `None` for top-level states.
    fn parent(self) -> Option<Self>;

    /// The child states in document order.
    fn children(self) -> &'static [Self];

    /// The state with this identifier.
    fn from_id(id: &str) -> Option<Self> {
        Self::ALL.iter().copied().find(|s| s.id() == id)
    }

    /// Whether `self` is `other` or one of its ancestors.
    fn contains(self, other: Self) -> bool {
        let mut s = Some(other);
        while let Some(x) = s {
            if x == self {
                return true;
            }
            s = x.parent();
        }
        false
    }
}

/// Everything the macros generate for one chart, tied together: implemented by the generated
/// `Statechart` marker type.
pub trait ChartSpec: 'static {
    /// The context struct.
    type Ctx: Context;
    /// The state enum.
    type State: StateEnum;
    /// The event enum.
    type Event: ChartEvent;

    /// The chart IR.
    fn chart() -> &'static Chart;

    /// The compiled chart.
    fn compiled() -> &'static CompiledChart;

    /// The registry binding the chart's guard and action IRIs to the Rust functions named in
    /// the chart.
    fn bind() -> Registry<Self::Ctx>;
}

/// Why a typed session could not start or step.
#[derive(Clone, Debug, PartialEq)]
pub enum MachineError {
    /// A guard or action IRI has no registered function.
    Unbound(Vec<RegistryError>),
    /// The session could not start.
    Start(StartError),
    /// The step was rejected or cut short.
    Step(StepError),
}

impl fmt::Display for MachineError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            MachineError::Unbound(errs) => {
                for (i, e) in errs.iter().enumerate() {
                    if i > 0 {
                        f.write_str("; ")?;
                    }
                    write!(f, "{e}")?;
                }
                Ok(())
            }
            MachineError::Start(e) => write!(f, "session start failed: {e:?}"),
            MachineError::Step(e) => write!(f, "step failed: {e:?}"),
        }
    }
}

impl std::error::Error for MachineError {}

/// A running session of a generated chart with its `rust` datamodel.
pub struct Machine<S: ChartSpec> {
    session: Session,
    dm: RustDatamodel<S::Ctx>,
    index: Vec<Option<StateIdx>>,
}

impl<S: ChartSpec> fmt::Debug for Machine<S>
where
    S::Ctx: fmt::Debug,
{
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Machine")
            .field("active", &self.active())
            .field("context", self.context())
            .finish()
    }
}

impl<S: ChartSpec> Machine<S> {
    /// Start a session with the functions the chart names ([`ChartSpec::bind`]).
    pub fn start(session_id: &str) -> Result<(Self, Vec<Effect>), MachineError> {
        Self::start_with(Arc::new(S::bind()), Self::start_input(session_id))
    }

    /// The start input for a session id: the chart's name as `_name`, no time and seed.
    pub fn start_input(session_id: &str) -> StartInput {
        StartInput {
            info: SessionInfo {
                sessionid: session_id.to_string(),
                name: S::chart().name.clone(),
                ..SessionInfo::default()
            },
            ..StartInput::default()
        }
    }

    /// Start a session with an explicit registry and start input.
    pub fn start_with(
        registry: Arc<Registry<S::Ctx>>,
        input: StartInput,
    ) -> Result<(Self, Vec<Effect>), MachineError> {
        let chart = S::compiled();
        let mut dm =
            RustDatamodel::for_chart(chart.chart(), registry).map_err(MachineError::Unbound)?;
        let outcome = session::start(chart, input, &mut dm).map_err(MachineError::Start)?;
        let index = S::State::ALL
            .iter()
            .map(|s| chart.index_of(s.id()))
            .collect();
        Ok((
            Machine {
                session: outcome.session,
                dm,
                index,
            },
            outcome.effects,
        ))
    }

    /// Process one typed external event.
    pub fn send(&mut self, event: S::Event) -> Result<Vec<Effect>, MachineError> {
        self.send_event(event.to_event(), Environment::default())
    }

    /// Process one external event in the given environment.
    pub fn send_event(
        &mut self,
        event: Event,
        env: Environment,
    ) -> Result<Vec<Effect>, MachineError> {
        self.step(Input::event(event, env)).map(|o| o.effects)
    }

    /// Process one input, returning the whole outcome.
    pub fn step(&mut self, input: Input) -> Result<Outcome, MachineError> {
        let outcome = session::step(S::compiled(), self.session.clone(), input, &mut self.dm)
            .map_err(MachineError::Step)?;
        self.session = outcome.session.clone();
        Ok(outcome)
    }

    /// Whether `state` is active.
    pub fn is_in(&self, state: S::State) -> bool {
        self.index
            .get(state.index())
            .copied()
            .flatten()
            .is_some_and(|i| self.session.configuration.contains(i))
    }

    /// The active states in document order.
    pub fn active(&self) -> Vec<S::State> {
        S::State::ALL
            .iter()
            .copied()
            .filter(|s| self.is_in(*s))
            .collect()
    }

    /// The context.
    pub fn context(&self) -> &S::Ctx {
        self.dm.context()
    }

    /// The session value.
    pub fn session(&self) -> &Session {
        &self.session
    }

    /// The datamodel.
    pub fn datamodel(&self) -> &RustDatamodel<S::Ctx> {
        &self.dm
    }

    /// Whether the session has ended.
    pub fn is_terminated(&self) -> bool {
        self.session.is_terminated()
    }
}
